python3 - <<'PY'
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
wb=load_workbook('/root/data/workbook.xlsx', data_only=False)
ds=wb['Data']
print('Non-empty Data cells rows 1-20:')
for r in range(1,21):
    vals=[]
    for c in range(1,ds.max_column+1):
        v=ds.cell(r,c).value
        if v is not None:
            vals.append(f'{get_column_letter(c)}{r}={v!r}')
    if vals:
        print(r, vals)
print('\nCells with values matching year headers 2019-2023:')
for row in ds.iter_rows():
    for cell in row:
        if cell.value in [2019,2020,2021,2022,2023,'2019','2020','2021','2022','2023']:
            print(cell.coordinate, cell.value)
print('\nMerged ranges:', list(ds.merged_cells.ranges))
PY
